for (const auto& neighbor_pair : graph.get_adjacent_nodes(current_node))
{
    Node* neighbor = neighbor_pair.first;
    if (neighbor->visited || neighbor == current_node)
        continue;

    int g = current_node->g + neighbor_pair.second;  // g = cost from start to neighbor
    int h = std::abs(neighbor->x - end_node->x) + std::abs(neighbor->y - end_node->y);  // Manhattan distance
    int f = g + h;

    // Check if neighbor is already in open_list and has a better f value
    bool found = false;
    for (auto& node_in_list : open_list)
    {
        if (node_in_list == neighbor && f >= node_in_list->f)
        {
            found = true;
            break;
        }
    }

    if (!found)
    {
        neighbor->g = g;
        neighbor->h = h;
        neighbor->f = f;
        neighbor->parent = current_node;
        open_list.push_back(neighbor);
    }
}

std::sort(open_list.begin(), open_list.end(),
    [](Node* a, Node* b) { return a->f < b->f; });
// END_CODE

